import json
import sys

mode = sys.argv[1] if len(sys.argv) > 1 else "baseline"
if mode not in {"baseline", "disabled"}:
    raise SystemExit("Unsupported mode: use baseline or disabled.")

request = {"item": "notebook", "quantity": 3, "budget": 15}
context = {"conversation": "My budget is $15."}
catalog = {"notebook": {"unit_price": 4, "currency": "USD", "in_stock": True}}
retrieval_enabled = mode == "baseline"
if mode == "disabled":
    catalog = None

tools = {"catalog_lookup": "read_catalog_only"}
proposal = {"tool": "catalog_lookup", "arguments": {"item": request["item"]}}
trace = []
trace.append({"step": 1, "layer": "interface", "event": "request_received"})
trace.append({"step": 2, "layer": "conversation_context", "event": "context_supplied", "context": context})
trace.append({"step": 3, "layer": "model", "event": "proposal", "proposal": proposal})
permission = retrieval_enabled and tools.get("catalog_lookup") == "read_catalog_only"
trace.append({"step": 4, "layer": "policy", "event": "permission_check", "allowed": permission, "reason": "read-only lookup only"})
retrieved = None
if not retrieval_enabled:
    trace.append({"step": 5, "layer": "retrieval", "event": "disabled"})
else:
    trace.append({"step": 5, "layer": "retrieval", "event": "request", "item": request["item"]})
    if permission and catalog is not None:
        retrieved = catalog.get(request["item"])
    trace.append({"step": 6, "layer": "retrieval", "event": "return", "record": retrieved})
executed = permission and retrieved is not None
trace.append({"step": 7, "layer": "tool", "event": "execution", "executed": executed})
if executed:
    total = request["quantity"] * retrieved["unit_price"]
    remaining = request["budget"] - total
    answer = f"{request['quantity']} x {retrieved['unit_price']} = {total} {retrieved['currency']}; remaining budget = {remaining} {retrieved['currency']}."
    arithmetic = {"total": total, "remaining": remaining}
else:
    answer = "UNKNOWN: no permitted catalog result."
    arithmetic = "UNKNOWN"
trace.append({"step": 8, "layer": "deterministic_code", "event": "arithmetic", "result": arithmetic})
side_effect = {"purchase": False, "records_written": False}
trace.append({"step": 9, "layer": "runtime", "event": "side_effect", "result": side_effect})
result = {"mode": mode, "request": request, "context": context, "retrieval_enabled": retrieval_enabled, "retrieval_return": retrieved, "tool_executed": executed, "runtime_answer": answer, "side_effect": side_effect, "trace": trace}
if mode == "baseline":
    assert result["retrieval_return"]["unit_price"] == 4
    assert result["tool_executed"] is True
    assert result["runtime_answer"] == "3 x 4 = 12 USD; remaining budget = 3 USD."
    assert result["trace"][7]["result"] == {"total": 12, "remaining": 3}
elif mode == "disabled":
    assert result["retrieval_return"] is None
    assert result["tool_executed"] is False
    assert result["runtime_answer"] == "UNKNOWN: no permitted catalog result."
    assert result["trace"][6]["result"] == "UNKNOWN"
    assert all(event.get("event") != "return" for event in result["trace"])
assert result["side_effect"] == {"purchase": False, "records_written": False}
print(json.dumps(result, indent=2, sort_keys=True))

